"""Русский паспорт фактического окна creditsModal.

Файл описывает только существующий контракт расчёта и представления.  Формулы
для недоступных карточек ниже помечены как рекомендации и не выдаются за
реализованные расчёты.
"""


def table(text):
    rows = [line.strip().split("|") for line in text.strip().splitlines()]
    assert all(len(row) == len(rows[0]) for row in rows), [
        (i, len(row)) for i, row in enumerate(rows) if len(row) != len(rows[0])
    ]
    return rows


